package com.smarthub.plus;
import android.content.Context;import org.json.*;import java.time.*;import java.util.*;import java.io.*;
/** Documented OpenLigaDB fallback, community ODbL. No guessed LIVE status or previous season substitution. */
final class OpenLeagueSportsProvider implements SportsDataProvider {
 private final SportsCache cache;OpenLeagueSportsProvider(Context c){cache=new SportsCache(c);}public String name(){return "OpenLigaDB · community ODbL";}
 public List<SportsMatch> matches(LeagueRepository.League league,LocalDate day,String window)throws Exception{JSONArray catalog=cache.get("https://api.openligadb.de/getavailableleagues",6*3600000L).getJSONObject("data").optJSONArray("rows");String shortcut="";int season=day.getMonthValue()>=7?day.getYear():day.getYear()-1;int foundSeason=0;if(catalog!=null)for(int i=0;i<catalog.length();i++){JSONObject l=catalog.optJSONObject(i);if(l==null||l.optInt("leagueSeason")!=season)continue;JSONObject sport=l.optJSONObject("sport");if(sport!=null&&sport.optInt("sportId")!=1)continue;if(identifies(league,l.optString("leagueName"),l.optString("leagueShortcut"))){shortcut=l.optString("leagueShortcut");foundSeason=season;break;}}if(shortcut.isEmpty()||!shortcut.matches("[A-Za-z0-9_-]{1,50}"))throw new IOException("No verified current-season OpenLigaDB mapping");JSONObject wrapper=cache.get("https://api.openligadb.de/getmatchdata/"+shortcut+"/"+foundSeason,120000L);JSONArray rows=wrapper.getJSONObject("data").optJSONArray("rows");List<SportsMatch> out=new ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++){SportsMatch m=parse(rows.optJSONObject(i),league,wrapper.optLong("at"),wrapper.optBoolean("stale"));if(m==null)continue;LocalDate date=Instant.ofEpochMilli(m.kickoff).atZone(ZoneId.of("Asia/Baghdad")).toLocalDate();if(window.equals("day")&&!date.equals(day)||window.equals("next")&&(date.isBefore(day)||date.isAfter(day.plusDays(14)))||window.equals("past")&&(date.isAfter(day)||date.isBefore(day.minusDays(14))))continue;out.add(m);}return out;}
 static boolean identifies(LeagueRepository.League l,String name,String shortcut){String n=PlaylistRepository.normalize(name);if(n.equals(PlaylistRepository.normalize(l.name)))return true;return l.id.equals("4328")&&shortcut.equals("pl")&&n.startsWith("premier league")||l.id.equals("4331")&&shortcut.equals("bl1")&&n.contains("bundesliga")||l.id.equals("4335")&&shortcut.equals("la1")&&n.contains("laliga")||l.id.equals("4480")&&shortcut.equals("ucl")&&n.startsWith("champions league")||l.id.equals("4481")&&shortcut.equals("uel2026")&&n.startsWith("europa league")||l.id.equals("5071")&&shortcut.equals("uecl2026")&&n.startsWith("conference league");}
 static SportsMatch parse(JSONObject j,LeagueRepository.League l,long at,boolean stale){if(j==null||j.optInt("matchID")<=0)return null;JSONObject h=j.optJSONObject("team1"),a=j.optJSONObject("team2");if(h==null||a==null)return null;SportsMatch m=new SportsMatch();m.id="openliga:"+j.optInt("matchID");m.leagueId=l.id;m.league=l.name;m.homeId="openliga:"+h.optInt("teamId");m.awayId="openliga:"+a.optInt("teamId");m.home=h.optString("teamName");m.away=a.optString("teamName");m.homeShort=h.optString("shortName",m.home);m.awayShort=a.optString("shortName",m.away);JSONArray goals=j.optJSONArray("goals");if(goals!=null){StringBuilder details=new StringBuilder();for(int g=0;g<goals.length();g++){JSONObject goal=goals.optJSONObject(g);if(goal!=null&&!goal.isNull("goalGetterName"))details.append(goal.optString("matchMinute")).append(" · ").append(goal.optString("goalGetterName")).append(" · ").append(goal.optString("scoreTeam1")).append(":").append(goal.optString("scoreTeam2")).append('\n');}m.timeline=details.toString();}m.homeLogo=h.optString("teamIconUrl");m.awayLogo=a.optString("teamIconUrl");m.kickoff=SportsMatch.utc(j.optString("matchDateTimeUTC"));if(m.kickoff==0||m.home.isEmpty()||m.away.isEmpty())return null;m.status=j.optBoolean("matchIsFinished")?"FT":m.kickoff>System.currentTimeMillis()?"NS":"UNKNOWN";JSONArray results=j.optJSONArray("matchResults");JSONObject selected=null;if(results!=null)for(int i=0;i<results.length();i++){JSONObject r=results.optJSONObject(i);if(r==null)continue;if(selected==null||r.optInt("resultTypeID")==2)selected=r;}if(selected!=null&&(j.optBoolean("matchIsFinished")||goals!=null&&goals.length()>0)&&!selected.isNull("pointsTeam1")&&!selected.isNull("pointsTeam2")){m.homeScore=String.valueOf(selected.optInt("pointsTeam1"));m.awayScore=String.valueOf(selected.optInt("pointsTeam2"));}JSONObject location=j.optJSONObject("location");if(location!=null)m.venue=location.optString("locationStadium");m.source="OpenLigaDB · ODbL community · live coverage not guaranteed";m.updatedAt=at;m.cached=stale;return m;}
}
